interface OpportunityRepository {
    suspend fun get(id: OpportunityId): Result<Opportunity>
}

class LoadOpportunity(
    private val repository: OpportunityRepository
) {
    suspend operator fun invoke(id: OpportunityId): Result<Opportunity> =
        repository.get(id)
}

class NetworkOpportunityRepository(
    private val api: OpportunityApi
) : OpportunityRepository {
    override suspend fun get(id: OpportunityId) =
        runCatching { api.get(id.value).toDomain() }
}

class SendMessage(
    private val repository: ChatRepository,
    private val clock: Clock,
    private val ids: ClientIdGenerator
) {
    suspend operator fun invoke(conversationId: String, text: String): SendResult {
        val normalized = text.trim()
        require(normalized.isNotEmpty())
        val draft = OutgoingMessage(ids.next(), conversationId, normalized, clock.now())
        return repository.enqueueAndSend(draft)
    }
}

val chatModule = module {
    single<ChatRepository> { SocketChatRepository(get(), get(), get()) }
    factory { SendMessage(get(), get(), get()) }
    viewModel { ChatViewModel(sendMessage = get(), observeChat = get()) }
}
